<?php require 'config.php'; $search=trim($_GET['q']??''); $category=(int)($_GET['category']??0); $sort=$_GET['sort']??'popular'; $where='p.is_active=1'; $types=''; $params=[]; if($search){$where.=' AND (p.title LIKE ? OR p.description LIKE ?)';$types.='ss';$like="%$search%";$params=[$like,$like];} if($category){$where.=' AND p.category_id=?';$types.='i';$params[]=$category;} $order=$sort==='price_low'?'p.price ASC':($sort==='price_high'?'p.price DESC':'p.sales_count DESC'); $stmt=db()->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE $where ORDER BY $order"); if($types)$stmt->bind_param($types,...$params);$stmt->execute();$products=$stmt->get_result();$categories=db()->query('SELECT * FROM categories ORDER BY name'); page_start('Explore the library','shop'); ?>
<section class="section-space"><div class="container"><div class="eyebrow">The library</div><div class="d-flex justify-content-between align-items-end flex-wrap gap-3 mb-4"><h1 class="display-5 mb-0">Tools for the work ahead.</h1><span class="text-muted"><?= $products->num_rows ?> resources</span></div><form class="filterbar row g-2 mb-5"><div class="col-lg-6"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search templates, planners, kits..."></div><div class="col-md-3"><select class="form-select" name="category"><option value="0">All categories</option><?php while($c=$categories->fetch_assoc()): ?><option value="<?= $c['id'] ?>" <?= $category===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endwhile; ?></select></div><div class="col-md-3"><select class="form-select" name="sort"><option value="popular" <?= $sort==='popular'?'selected':'' ?>>Most popular</option><option value="price_low" <?= $sort==='price_low'?'selected':'' ?>>Price: low to high</option><option value="price_high" <?= $sort==='price_high'?'selected':'' ?>>Price: high to low</option></select></div></form><div class="row g-4 product-scroll"><?php while($product=$products->fetch_assoc()): ?><div class="col-md-6 col-lg-4"><?php include 'partials/product-card.php'; ?></div><?php endwhile; ?></div></div></section><?php page_end(); ?>